VOCAB = {0: "a", 1: "b", 2: "<eos>"}

def step_fn(ids):
    table = {(): 0, (0,): 1, (0, 1): 2}
    return table[tuple(ids)]

def greedy_decode(step_fn, init_ids, max_len, eos):
    ids = list(init_ids)
    while len(ids) < max_len:
        nxt = step_fn(ids)
        ids.append(nxt)
        if nxt == eos:
            break
    return ids

out = greedy_decode(step_fn, [], 5, 2)
print(out)
print("".join(VOCAB[i] for i in out))

